'use strict';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = value => JSON.parse(JSON.stringify(value));
const ONBOARDING_KEY = 'graphcore.studio.onboarding.v1';
const icons = {
 input:'<path d="M4 3h9l4 4v11H4zM12 3v5h5M7 12h7M7 15h4"/>',
 agent:'<rect x="4" y="6" width="14" height="11" rx="3"/><path d="M11 2v4M8 11h.01M14 11h.01M8 14h6M1 10v4M21 10v4"/>',
 model:'<path d="M3 5h16M3 11h16M3 17h10"/><circle cx="18" cy="17" r="3"/>',
 condition:'<path d="M5 3v4c0 4 12 0 12 5v6M5 7v11M2 15l3 3 3-3M14 15l3 3 3-3"/>',
 tool:'<path d="M8 4L2 10l6 6M14 4l6 6-6 6M12 2l-3 17"/>',
 schema:'<path d="M7 3H4v15h3M15 3h3v15h-3M8 10l2 2 4-5"/>',
 approval:'<path d="M7 9V5a2 2 0 014 0v5M11 8a2 2 0 014 0v3M15 10a2 2 0 014 0v4c0 4-4 6-7 5l-6-6a2 2 0 012-3l2 2V8"/>',
 output:'<path d="M12 3h6v15H4V8M2 3h8M7 0l3 3-3 3M7 12h7M7 15h4"/>',
 retrieve:'<path d="M10 3a7 7 0 105.3 11.6L20 19.3M10 6v4l3 2"/>'
};
const META = {
 input:{name:'Input',sub:'Where your workflow begins',group:'FLOW',color:'#709688',bg:'#edf6f1'},
 agent:{name:'Agent',sub:'Reason, write, and collaborate',group:'INTELLIGENCE',color:'#9480c8',bg:'#f1ecfb'},
 model:{name:'Chat Model',sub:'Compose role-based model messages',group:'INTELLIGENCE',color:'#718dc4',bg:'#edf2fb'},
 condition:{name:'Condition',sub:'Route with if / else logic',group:'FLOW',color:'#c59d63',bg:'#fbf3e6'},
 tool:{name:'Python tool',sub:'Bring your libraries along',group:'INTEGRATIONS',color:'#779bc1',bg:'#edf3fb'},
 data_group:{name:'Grouped summary',sub:'Exact totals for each typed group',group:'INTEGRATIONS',color:'#599e91',bg:'#eaf6f1'},
 data_filter:{name:'Table filter',sub:'Keep rows using typed comparisons',group:'INTEGRATIONS',color:'#599e91',bg:'#eaf6f1'},
 data:{name:'Data summary',sub:'Exact calculations on local tables',group:'INTEGRATIONS',color:'#599e91',bg:'#eaf6f1'},
 retrieve:{name:'Document retrieval',sub:'Search your local knowledge library',group:'INTEGRATIONS',color:'#599e91',bg:'#eaf6f1'},
 schema:{name:'Structured output',sub:'Validate with a typed schema',group:'INTELLIGENCE',color:'#b381a4',bg:'#f9edf5'},
 approval:{name:'Human approval',sub:'Pause for a human decision',group:'FLOW',color:'#bf956e',bg:'#fbf2e9'},
 output:{name:'Output',sub:'Return your final result',group:'FLOW',color:'#7aa39a',bg:'#edf6f4'}
};
const icon = kind => `<span class="node-icon" style="--node-color:${META[kind]?.color};--node-bg:${META[kind]?.bg}"><svg viewBox="0 0 22 22">${icons[kind]||icons.agent}</svg></span>`;
const S = {workflow:null,selected:null,library:'nodes',tab:'input',bootstrap:null,view:{x:35,y:55,z:.8},undo:[],redo:[],run:null,nodeStatus:{},connection:null,inputText:'{}',poll:null,dirty:false,models:{}};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(path, body, method){const response=await fetch(path,{method:method||(body===undefined?'GET':'POST'),headers:body===undefined?{'X-Studio-Token':S.bootstrap?.csrf}:{'Content-Type':'application/json','X-Studio-Token':S.bootstrap.csrf},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');return data;}
function mark(){S.undo.push(clone(S.workflow));if(S.undo.length>60)S.undo.shift();S.redo=[];}
function changed(){S.dirty=true;$('#save-status').textContent='Unsaved changes';try{localStorage.setItem('graphcore.studio.draft',JSON.stringify(S.workflow));}catch{}$('#undo-button').disabled=!S.undo.length;$('#redo-button').disabled=!S.redo.length;}
function load(workflow){if(S.poll){clearTimeout(S.poll);S.poll=null;}S.workflow=clone(workflow);for(const n of S.workflow.nodes){if(['agent','model'].includes(n.type)&&n.config&&n.config.provider&& !['demo','openrouter'].includes(n.config.provider)){const old=n.config.provider;n.config.provider='openrouter';if(!String(n.config.model||'').includes('/'))n.config.model=old==='openai'?'openai/'+(n.config.model||'gpt-4o-mini'):old==='anthropic'?'anthropic/'+(n.config.model||'claude-sonnet-4'):old==='google_genai'?'google/'+(n.config.model||'gemini-2.5-flash'):'openai/gpt-4o-mini';}}S.selected=workflow.nodes.find(n=>n.type==='agent')?.id||workflow.nodes[0]?.id;S.inputText=JSON.stringify(workflow.inputs||{},null,2);S.undo=[];S.redo=[];S.run=null;S.nodeStatus={};S.connection=null;S.tab='input';S.dirty=false;renderAll();$('#save-status').textContent='Local draft';requestAnimationFrame(fit);try{localStorage.setItem('graphcore.studio.draft',JSON.stringify(S.workflow));}catch{}}
function renderAll(){if(!S.workflow)return;$('#workflow-name').value=S.workflow.name;$('#breadcrumb').textContent=S.workflow.name;$('#workflow-description').textContent=S.workflow.description||'Build a team of agents. Connect the way they think.';renderLibrary();renderNodes();renderInspector();renderConsole();$('#undo-button').disabled=!S.undo.length;$('#redo-button').disabled=!S.redo.length;}
function renderLibrary(){const text=$('#node-search').value.toLowerCase();document.querySelectorAll('[data-library]').forEach(b=>b.classList.toggle('active',b.dataset.library===S.library));let html='';if(S.library==='templates'){html=S.bootstrap.templates.map((t,i)=>`<button class="template-card" data-template="${i}">${icon(i===1?'schema':i===2?'tool':'agent')}<strong>${esc(t.name)}</strong><p>${esc(t.description)}</p><small>${t.nodes.length} nodes &nbsp;↗&nbsp; Open template</small></button>`).join('');html+='<button class="template-card" id="blank-template"><strong>＋ Start from scratch</strong><p>A blank canvas for your next idea.</p></button>';}else{for(const group of ['INTELLIGENCE','FLOW','INTEGRATIONS']){const kinds=Object.keys(META).filter(k=>META[k].group===group&&`${META[k].name} ${META[k].sub}`.toLowerCase().includes(text));if(!kinds.length)continue;html+=`<div class="library-group">${group}</div>`;for(const kind of kinds){const m=META[kind];html+=`<button class="palette-node" draggable="true" data-kind="${kind}" aria-label="Add ${m.name}">${icon(kind)}<span><strong>${m.name}</strong><small>${m.sub}</small></span><span class="grab">⠿</span></button>`;}}}$('#node-library').innerHTML=html;document.querySelectorAll('.palette-node').forEach(el=>{el.addEventListener('dragstart',e=>{e.dataTransfer.setData('application/graphcore-node',el.dataset.kind);e.dataTransfer.effectAllowed='copy';});el.onclick=()=>{const area=$('#canvas-area');addNode(el.dataset.kind,(area.clientWidth/2-S.view.x)/S.view.z-113,(area.clientHeight/2-S.view.y)/S.view.z-54);};});document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>confirmReplace(()=>load(S.bootstrap.templates[+b.dataset.template])));if($('#blank-template'))$('#blank-template').onclick=()=>confirmReplace(()=>load({format:'graphcore.studio.v1',id:'workflow_'+Date.now(),name:'Untitled workflow',description:'A blank canvas for your next idea.',inputs:{input:'Hello, world'},nodes:[],edges:[]}));}
function confirmReplace(action){if(!S.dirty){action();return;}showModal('Replace this draft?',`<p class="modal-copy">Save or export your current workflow first if you want to keep it.</p><div class="modal-actions"><button class="button" id="keep-draft">Keep editing</button><button class="button primary" id="replace-draft">Replace draft</button></div>`);$('#keep-draft').onclick=closeModal;$('#replace-draft').onclick=()=>{closeModal();action();};}
function nodeSubtitle(n){const c=n.config||{};if(n.type==='agent'||n.type==='model')return c.provider==='demo'?'Offline fixture':`${c.provider||'openrouter'} · ${c.model||'choose model'}`;if(n.type==='condition')return `${c.field||'field'} equals ${JSON.stringify(c.expected)}`;if(n.type==='tool')return c.tool||'word_count';if(n.type==='retrieve')return `Local library · top ${c.top_k||4}`;if(n.type==='schema')return c.engine==='pydantic'?'Pydantic validation':'Portable schema validation';return META[n.type]?.sub||n.type;}
function renderNodes(){const w=S.workflow;$('#nodes').innerHTML=w.nodes.map(n=>{const m=META[n.type]||META.agent;const selected=S.selected===n.id;const c=n.config||{};return `<div class="canvas-node ${esc(n.type)} ${selected?'selected':''} ${S.nodeStatus[n.id]||''}" id="node-${esc(n.id)}" data-node="${esc(n.id)}" style="left:${Number(n.x)||0}px;top:${Number(n.y)||0}px" tabindex="0" role="group" aria-label="${esc(n.label)} node"><div class="node-head">${icon(n.type)}<div><strong>${esc(n.label||m.name)}</strong><small>${esc(nodeSubtitle(n))}</small></div><span class="node-menu">⋮</span></div><div class="node-foot"><span>${n.type==='condition'?'C++ routing':n.type==='agent'?'Agent':esc(m.name)}</span><code>${esc(n.type==='input'?'workflow inputs':n.type==='output'?'output':c.output_key||n.type==='condition'&&'true / false'||n.id)}</code></div>${n.type!=='input'?`<button class="port input" data-target="${esc(n.id)}" aria-label="Connect to ${esc(n.label)}"></button>`:''}${n.type==='condition'?`<button class="port output true" data-source="${esc(n.id)}" data-port="true" aria-label="True branch from ${esc(n.label)}"></button><button class="port output false" data-source="${esc(n.id)}" data-port="false" aria-label="False branch from ${esc(n.label)}"></button>`:n.type!=='output'?`<button class="port output" data-source="${esc(n.id)}" data-port="next" aria-label="Connect from ${esc(n.label)}"></button>`:''}</div>`;}).join('');$('#empty-canvas').hidden=w.nodes.length>0;$('#graph-stats').textContent=`${w.nodes.length} nodes · ${w.edges.length} connections`;const real=w.nodes.filter(n=>['agent','model'].includes(n.type)&&(n.config?.provider||'demo')!=='demo');$('#mode-label').textContent=real.length?`${real.length} model node${real.length===1?'':'s'} · ${new Set(real.map(n=>n.config.model)).size} selection${new Set(real.map(n=>n.config.model)).size===1?'':'s'}`:'Offline demo · no model calls';document.querySelectorAll('.canvas-node').forEach(el=>{el.addEventListener('pointerdown',startNodeDrag);el.addEventListener('keydown',e=>{if(e.key==='Enter'){selectNode(el.dataset.node);}});});document.querySelectorAll('.port.output').forEach(el=>{el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();S.connection={source:el.dataset.source,port:el.dataset.port};toast('Select an input port to connect.');}});el.addEventListener('pointerdown',e=>{e.stopPropagation();S.connection={source:el.dataset.source,port:el.dataset.port};$('#canvas-hint').textContent='Click an input dot to connect · Esc to cancel';el.classList.add('connecting');});});document.querySelectorAll('.port.input').forEach(el=>{el.addEventListener('keydown',e=>{if(e.key==='Enter'&&S.connection){e.preventDefault();connect(S.connection.source,el.dataset.target,S.connection.port);}});el.addEventListener('pointerdown',e=>{e.stopPropagation();if(S.connection)connect(S.connection.source,el.dataset.target,S.connection.port);});});applyView();drawEdges();}
function dimensions(node){const el=document.getElementById('node-'+node.id);return {w:226,h:el?.offsetHeight||108};}
function anchor(node,side,port){const d=dimensions(node);return {x:(Number(node.x)||0)+(side==='out'?d.w:0),y:(Number(node.y)||0)+d.h*(port==='true'?.35:port==='false'?.72:.5)};}
function curve(a,b){const distance=Math.max(70,Math.abs(b.x-a.x)*.5);return `M ${a.x} ${a.y} C ${a.x+distance} ${a.y}, ${b.x-distance} ${b.y}, ${b.x} ${b.y}`;}
function drawEdges(){if(!S.workflow)return;const nodes=new Map(S.workflow.nodes.map(n=>[n.id,n]));let html='<defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" style="fill:#c8bfdc;stroke:none"/></marker></defs>';for(const e of S.workflow.edges){const a=nodes.get(e.source),b=nodes.get(e.target);if(!a||!b)continue;const start=anchor(a,'out',e.port),end=anchor(b,'in');html+=`<path d="${curve(start,end)}" marker-end="url(#arrow)" class="${S.nodeStatus[a.id]==='completed'&&S.nodeStatus[b.id]?'ran':''}"/><text x="${start.x+14}" y="${start.y-10}">${e.port&&e.port!=='next'?esc(e.port):''}</text>`;}if(S.connection?.point){const n=nodes.get(S.connection.source);if(n)html+=`<path d="${curve(anchor(n,'out',S.connection.port),S.connection.point)}" style="stroke:#a28bd2;stroke-dasharray:5 4"/>`;}$('#edges').innerHTML=html;}
function applyView(){$('#world').style.transform=`translate(${S.view.x}px,${S.view.y}px) scale(${S.view.z})`;$('#zoom-label').textContent=Math.round(S.view.z*100)+'%';}
function fit(){const area=$('#canvas-area'),nodes=S.workflow.nodes;if(!nodes.length){S.view={x:50,y:70,z:1};applyView();return;}const minX=Math.min(...nodes.map(n=>n.x)),minY=Math.min(...nodes.map(n=>n.y));const width=Math.max(...nodes.map(n=>n.x+226))-minX,height=Math.max(...nodes.map(n=>n.y+115))-minY;const z=Math.max(.3,Math.min(1.1,(area.clientWidth-100)/width,(area.clientHeight-115)/height));S.view={z,x:(area.clientWidth-width*z)/2-minX*z,y:(area.clientHeight-height*z)/2-minY*z+6};applyView();}
function zoom(factor,x,y){const area=$('#canvas-area');x??=area.clientWidth/2;y??=area.clientHeight/2;const z=Math.max(.25,Math.min(1.8,S.view.z*factor)),r=z/S.view.z;S.view.x=x-(x-S.view.x)*r;S.view.y=y-(y-S.view.y)*r;S.view.z=z;applyView();}
function worldPoint(e){const rect=$('#canvas-area').getBoundingClientRect();return {x:(e.clientX-rect.left-S.view.x)/S.view.z,y:(e.clientY-rect.top-S.view.y)/S.view.z};}
let drag=null;
function startNodeDrag(e){if(e.target.closest('.port')||e.button!==0)return;e.stopPropagation();const id=e.currentTarget.dataset.node;selectNode(id,false);const n=S.workflow.nodes.find(n=>n.id===id);drag={type:'node',id,x:e.clientX,y:e.clientY,originalX:n.x,originalY:n.y,moved:false};}
document.addEventListener('pointermove',e=>{if(S.connection){S.connection.point=worldPoint(e);drawEdges();}if(!drag)return;if(drag.type==='pan'){S.view.x=drag.vx+e.clientX-drag.x;S.view.y=drag.vy+e.clientY-drag.y;applyView();return;}const dx=(e.clientX-drag.x)/S.view.z,dy=(e.clientY-drag.y)/S.view.z;if(!drag.moved&&Math.abs(dx)+Math.abs(dy)>3){mark();drag.moved=true;}if(!drag.moved)return;const node=S.workflow.nodes.find(n=>n.id===drag.id);node.x=Math.max(-500,Math.round((drag.originalX+dx)/5)*5);node.y=Math.max(-500,Math.round((drag.originalY+dy)/5)*5);const el=document.getElementById('node-'+node.id);el.style.left=node.x+'px';el.style.top=node.y+'px';drawEdges();});
document.addEventListener('pointerup',e=>{if(drag?.moved)changed();drag=null;if(S.connection){const el=document.elementFromPoint(e.clientX,e.clientY)?.closest('.port.input');if(el)connect(S.connection.source,el.dataset.target,S.connection.port);}});
function selectNode(id,repaint=true){S.selected=id;if(innerWidth<=850)document.querySelector('.inspector').classList.add('mobile-open');if(repaint)renderNodes();else document.querySelectorAll('.canvas-node').forEach(el=>el.classList.toggle('selected',el.dataset.node===id));renderInspector();}
function connect(source,target,port='next'){if(source===target){toast('Connect to another node. Use a condition to build a loop.');return;}mark();S.workflow.edges=S.workflow.edges.filter(e=>!(e.source===source&&(e.port||'next')===port));S.workflow.edges.push({source,target,port});S.connection=null;$('#canvas-hint').textContent='Drag to arrange · connect the dots to build a flow';changed();renderNodes();renderInspector();}
function defaults(kind){return {input:{},agent:{provider:'demo',model:'openai/gpt-4o-mini',system:'You are a helpful assistant.',prompt:'{{input}}',demo_response:'Demo response: {{input}}',output_key:'response'},model:{provider:'demo',model:'openai/gpt-4o-mini',messages:[{role:'system',content:'You are a helpful assistant.'},{role:'user',content:'{{input}}'}],temperature:.2,max_tokens:1024,timeout:60,demo_response:'Demo response: {{input}}',output_key:'response'},condition:{field:'approved',expected:true},tool:{tool:'word_count',input_field:'input',output_key:'tool_result'},data_group:{input_field:'table',group_column:'customer',column:'amount',null_keys:'include',max_groups:100,output_key:'grouped'},data_filter:{input_field:'table',column:'amount',operator:'gte',value:'0',output_key:'filtered'},data:{input_field:'table',column:'amount',output_key:'summary'},retrieve:{library:'default',input_field:'input',top_k:4,output_key:'context'},schema:{input_field:'record',output_key:'validated',engine:'builtin',fields:[{name:'summary',type:'string',required:true}]},approval:{prompt:'Approve this result?',output_key:'approved'},output:{template:'{{input}}'}}[kind];}
function addNode(kind,x,y){if(kind==='input'&&S.workflow.nodes.some(n=>n.type==='input')){toast('A workflow has one Input node.');return;}mark();const id=kind+'_'+Math.random().toString(36).slice(2,7);const config=defaults(kind);if(config.output_key&&kind!=='retrieve')config.output_key=id;if(kind==='retrieve'){let key='context',suffix=2;const used=new Set([...Object.keys(S.workflow.inputs||{}),...S.workflow.nodes.map(n=>n.config?.output_key)]);while(used.has(key))key='context_'+suffix++;config.output_key=key;}S.workflow.nodes.push({id,type:kind,label:META[kind].name,x:Math.round(x),y:Math.round(y),config});S.selected=id;if(innerWidth<=850)document.querySelector('.inspector').classList.add('mobile-open');changed();renderNodes();renderInspector();}
function field(label,key,value,options={}){let input;if(options.select)input=`<select data-config="${key}">${options.select.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;else if(options.area)input=`<textarea data-config="${key}" ${options.json?'data-json="true" class="code"':''} rows="${options.rows||4}">${esc(value)}</textarea>`;else input=`<input data-config="${key}" value="${esc(value)}" ${options.json?'data-json="true" class="code"':''}>`;return `<label class="field"><span>${esc(label)}</span>${input}${options.help?`<small>${esc(options.help)}</small>`:''}</label>`;}
function availableVariables(){const vars=new Map();const add=(key,label)=>{if(/^[A-Za-z_][A-Za-z0-9_.]*$/.test(key))vars.set(key,label);};for(const [key,value] of Object.entries(S.workflow.inputs||{})){add(key,`Input · ${key}`);if(value&&typeof value==='object'&&!Array.isArray(value))for(const child of Object.keys(value))add(`${key}.${child}`,`Input · ${key}.${child}`);}for(const other of S.workflow.nodes){if(['input','condition','output'].includes(other.type))continue;const key=other.config?.output_key||other.id;add(key,`Output · ${other.label||key}`);if(other.type==='schema')for(const f of other.config?.fields||[])add(`${key}.${f.name}`,`Output · ${key}.${f.name}`);}return [...vars].sort(([a],[b])=>a.localeCompare(b));}
function messageEditor(messages){const variables=availableVariables();return `<div class="message-list">${messages.map((message,i)=>`<section class="message-card"><header><select data-message-role="${i}" aria-label="Message ${i+1} role">${['system','user','assistant'].map(role=>`<option value="${role}" ${role===message.role?'selected':''}>${role}</option>`).join('')}</select><button class="message-remove" data-message-remove="${i}" aria-label="Remove message ${i+1}" ${messages.length<=1?'disabled':''}>×</button></header><textarea class="message-content" data-message-content="${i}" rows="4" aria-label="${message.role} message">${esc(message.content)}</textarea><div class="message-tools"><select data-message-variable="${i}" aria-label="Insert workflow variable into message ${i+1}"><option value="">＋ Insert variable…</option>${variables.map(([key,label])=>`<option value="${esc(key)}">{{${esc(key)}}} · ${esc(label)}</option>`).join('')}</select><small>Inserted at the cursor</small></div></section>`).join('')}</div><button class="button small" id="add-message">＋ Add message</button>`;}
function modelEditor(node){
 const c=node.config||(node.config={});
 if(!Array.isArray(c.messages)||!c.messages.length)c.messages=[{role:'system',content:c.system||'You are a helpful assistant.'},{role:'user',content:c.prompt||'{{input}}'}];
 let provider=c.provider||'demo';
 if(provider!=='demo'&&provider!=='openrouter'){c.provider='openrouter';if(!String(c.model||'').includes('/'))c.model='openai/gpt-4o-mini';provider='openrouter';}
 const router=S.bootstrap.providers.find(p=>p.id==='openrouter');
 const providers=[['demo','Offline fixture · no model call'],['openrouter',`OpenRouter${router?.installed?'':' · install openrouter SDK'}`]];
 let html='<div class="inspector-section">MODEL BACKEND</div>';
 html+=field('Provider','provider',provider,{select:providers});
 if(provider==='demo')html+=field('Demo response fixture','demo_response',c.demo_response||'Demo response: {{input}}',{area:true,rows:2,help:'Used for offline testing. It does not call a model.'});
 else {
  html+=field('Model selection','model',c.model||'openai/gpt-4o-mini',{help:'Use $model1 for a saved model variable, or enter an OpenRouter model ID directly.'});
  html+=`<label class="field"><span>Insert saved model</span><select id="model-variable"><option value="">Choose a model variable…</option>${Object.entries(S.models).map(([name,id])=>`<option value="$${esc(name)}" ${c.model==='$'+name?'selected':''}>$${esc(name)} · ${esc(id)}</option>`).join('')}</select><small>Manage model variables in Model integrations.</small></label>`;
  html+='<div class="inspector-note">Add <strong>OPENROUTER_API_KEY</strong> in <strong>Model integrations</strong>. OpenRouter model calls run through GraphCore’s Python bridge.</div>';
  if(router&&!router.installed)html+='<div class="inspector-note">Install the SDK in the Python environment running Studio: <code>python -m pip install openrouter</code>, then restart Studio.</div>';
 }
 html+='<div class="inspector-section">MESSAGES</div><div class="inspector-note">Compose system, user, and assistant messages. Use the variable menu to insert values from workflow inputs and upstream node outputs.</div>';
 html+=messageEditor(c.messages);
 html+='<div class="inspector-section">MODEL SETTINGS</div>';
 html+=field('Temperature','temperature',c.temperature??.2);
 html+=field('Maximum output tokens','max_tokens',c.max_tokens??1024);
 html+=field('Request timeout (seconds)','timeout',c.timeout??60);
 html+=`<label class="check-field"><input type="checkbox" id="json-output" ${c.json_output?'checked':''}> Request JSON output</label>`;
 return html;
}
function renderInspector(){const node=S.workflow.nodes.find(n=>n.id===S.selected);if(!node){$('#inspector-content').innerHTML='<div class="inspector-empty"><span class="empty-symbol" style="margin:auto auto 15px">◇</span><strong>Make it your own.</strong>Select a node to configure its behavior.</div>';return;}const kind=node.type,c=node.config||{},m=META[kind];$('#inspector-count').textContent=String(S.workflow.nodes.indexOf(node)+1).padStart(2,'0');let html=`<div class="inspector-hero">${icon(kind)}<div><strong>${esc(m.name)}</strong><p>${esc(m.sub)}</p></div></div><label class="field"><span>Node name</span><input id="node-label" value="${esc(node.label)}"></label>`;
if(kind==='input'){html+='<div class="inspector-note">Set the initial state in the <strong>Input</strong> panel below the canvas. Other nodes can reference fields with <strong>{{field_name}}</strong>.</div>';}
if(kind==='agent'||kind==='model'){html+=modelEditor(node);}
if(kind==='condition'){html+='<div class="inspector-section">IF THIS IS TRUE</div>';html+=field('State field','field',c.field||'approved',{help:'A top-level state field. Compared directly by C++.'});html+=field('Equals (JSON value)','expected',JSON.stringify(c.expected??true),{json:true,help:'Examples: true, 5, "research". Types must match.'});html+='<div class="inspector-note">Connect both the <strong>true</strong> and <strong>false</strong> outputs. A missing state field fails the run.</div>';}
if(kind==='tool'){html+='<div class="inspector-section">PYTHON INTEGRATION</div>';html+=field('Registered function','tool',c.tool||'word_count',{select:S.bootstrap.tools.map(t=>[t.name,t.name])});html+=field('Input state field','input_field',c.input_field||'input');html+='<div class="inspector-note">Connect your own Python libraries through a registered tool. Start Studio with <strong>--plugin path/to/tools.py</strong>. No code is executed from the canvas.</div>';}
if(kind==='retrieve'){html+='<div class="inspector-section">LOCAL KNOWLEDGE</div>';html+='<div class="inspector-note">Searches text documents in your local library and returns ranked passages with source names. Add files from <strong>Knowledge library</strong> in the left sidebar.</div>';html+=field('Query state field','input_field',c.input_field||'input',{help:'For example: input, question, or request.topic'});html+=field('Passages to return','top_k',c.top_k??4,{help:'BM25 keyword ranking, from 1 to 10.'});}
if(kind==='data_group'){html+='<div class="inspector-note">Creates a local table with group_key, row_count, count, null_count, sum, min and max. Group order follows first appearance. View the table in Data workspace; full rows stay outside workflow state.</div>';html+=field('Table reference state field','input_field',c.input_field||'table');html+=field('Group column','group_column',c.group_column||'customer');html+=field('Numeric column','column',c.column||'amount');html+=field('Null group keys','null_keys',c.null_keys||'include',{select:[['include','Include as a separate group'],['exclude','Exclude rows with null group keys']]});html+=field('Maximum groups','max_groups',c.max_groups??100,{help:'1–500. Exceeding the limit fails without saving a partial result.'});}
if(kind==='data_filter'){html+='<div class="inspector-note">Returns a new immutable table reference. Null cells only match Is null or Is not null. Connect to Data summary using this node’s output field.</div>';html+=field('Table reference state field','input_field',c.input_field||'table');html+=field('Column','column',c.column||'amount');html+=field('Comparison','operator',c.operator||'eq',{select:[['eq','Equals'],['ne','Does not equal'],['gt','Greater than'],['gte','At least'],['lt','Less than'],['lte','At most'],['contains','Contains text'],['is_null','Is null'],['not_null','Is not null']]});if(!['is_null','not_null'].includes(c.operator))html+=field('Comparison value','value',c.value??'',{help:'Enter text, a whole number, exact decimal, or true/false according to the column type. Text matching is case-sensitive.'});}
if(kind==='data'){html+='<div class="inspector-note">Upload a CSV in <strong>Data workspace</strong>, declare numeric column types, then use its table reference as an input. Results include exact decimal sum, minimum, maximum and null counts.</div>';html+=field('Table reference state field','input_field',c.input_field||'table');html+=field('Numeric column','column',c.column||'amount');}
if(kind==='schema'){html+='<div class="inspector-section">VALIDATION</div>';html+=field('Input state field','input_field',c.input_field||'record');html+=field('Validation engine','engine',c.engine||'builtin',{select:[['builtin','Built-in strict validation'],['pydantic',S.bootstrap.pydantic?'Pydantic · installed':'Pydantic · installation needed']],help:S.bootstrap.pydantic?'Pydantic is available in the server environment.':'Pydantic is optional. Install it in the server environment to enable it.'});html+='<div class="inspector-section">OUTPUT SCHEMA</div><div class="schema-legend"><span>Field name / type</span><span>Required</span></div>';html+=(c.fields||[]).map((f,i)=>`<div class="schema-row" data-index="${i}"><input aria-label="Schema field name" data-schema="name" value="${esc(f.name)}"><select aria-label="Schema field type" data-schema="type">${['string','integer','number','boolean','object','array'].map(t=>`<option ${t===f.type?'selected':''}>${t}</option>`).join('')}</select><input class="required" type="checkbox" aria-label="Required field" data-schema="required" ${f.required!==false?'checked':''}><button data-remove-field="${i}" aria-label="Remove field">×</button></div>`).join('');html+='<button class="button small" id="add-schema-field">＋ Add field</button>';}
if(kind==='approval'){html+='<div class="inspector-section">HUMAN IN THE LOOP</div>';html+=field('Question / review text','prompt',c.prompt||'',{area:true,rows:6,help:'The run saves a checkpoint and pauses until you respond.'});html+='<div class="inspector-note">The response is saved to the output field. Add a <strong>Condition</strong> after this node to branch on approval or rejection.</div>';}
if(kind==='output'){html+=field('Result template','template',c.template||'{{input}}',{area:true,rows:7,help:'Combine state fields into your final result.'});}
if(!['input','condition','output'].includes(kind)){html+='<div class="inspector-section">STATE</div>';html+=field('Save output to','output_key',c.output_key||node.id,{help:'Other nodes can read this field.'});}
html+='<div class="inspector-section">CONNECTIONS</div>';const ports=kind==='condition'?['true','false']:kind==='output'?[]:['next'];for(const port of ports){const edge=S.workflow.edges.find(e=>e.source===node.id&&(e.port||'next')===port);html+=`<div class="connection-row"><span>${port} →</span><select data-route="${port}" aria-label="${port} target"><option value="">Not connected</option>${S.workflow.nodes.filter(n=>n.id!==node.id&&n.type!=='input').map(n=>`<option value="${esc(n.id)}" ${edge?.target===n.id?'selected':''}>${esc(n.label)}</option>`).join('')}</select></div>`;}if(!ports.length)html+='<div class="field-help">This node completes the workflow.</div>';html+='<button class="button delete-node" id="delete-node">Delete node</button>';$('#inspector-content').innerHTML=html;
$('#node-label').onchange=e=>{mark();node.label=e.target.value||META[kind].name;changed();renderNodes();};document.querySelectorAll('[data-config]').forEach(el=>el.onchange=()=>{let value=el.value;try{if(el.dataset.json)value=JSON.parse(value);if(['temperature','max_tokens','timeout','top_k','max_groups'].includes(el.dataset.config))value=Number(value);mark();node.config[el.dataset.config]=value;if(el.dataset.config==='provider'&&value==='openrouter'&&!String(node.config.model||'').includes('/')&&!String(node.config.model||'').startsWith('$'))node.config.model='openai/gpt-4o-mini';changed();renderNodes();if(['provider','engine','operator'].includes(el.dataset.config))renderInspector();}catch(error){toast('Invalid JSON value: '+error.message);el.setAttribute('aria-invalid','true');}});document.querySelectorAll('[data-message-role]').forEach(el=>el.onchange=()=>{mark();node.config.messages[+el.dataset.messageRole].role=el.value;changed();});document.querySelectorAll('[data-message-content]').forEach(el=>{el.addEventListener('input',()=>{if(!el.dataset.historyMarked){mark();el.dataset.historyMarked='1';}node.config.messages[+el.dataset.messageContent].content=el.value;changed();});el.addEventListener('blur',()=>{delete el.dataset.historyMarked;});});document.querySelectorAll('[data-message-variable]').forEach(el=>el.onchange=()=>{const name=el.value;if(!name)return;const area=[...document.querySelectorAll('[data-message-content]')].find(a=>a.dataset.messageContent===el.dataset.messageVariable);const token='{{'+name+'}}';const start=area.selectionStart??area.value.length,end=area.selectionEnd??start;area.setRangeText(token,start,end,'end');node.config.messages[+el.dataset.messageVariable].content=area.value;changed();area.focus();el.value='';});document.querySelectorAll('[data-message-remove]').forEach(el=>el.onclick=()=>{mark();node.config.messages.splice(+el.dataset.messageRemove,1);changed();renderInspector();});if($('#add-message'))$('#add-message').onclick=()=>{if(node.config.messages.length>=20){toast('A model can have up to 20 messages.');return;}mark();node.config.messages.push({role:'user',content:''});changed();renderInspector();document.querySelectorAll('[data-message-content]')[node.config.messages.length-1]?.focus();};if($('#model-variable'))$('#model-variable').onchange=e=>{if(!e.target.value)return;mark();node.config.model=e.target.value;changed();renderNodes();renderInspector();};if($('#json-output'))$('#json-output').onchange=e=>{mark();node.config.json_output=e.target.checked;changed();};document.querySelectorAll('[data-schema]').forEach(el=>el.onchange=()=>{mark();node.config.fields[+el.closest('[data-index]').dataset.index][el.dataset.schema]=el.type==='checkbox'?el.checked:el.value;changed();});document.querySelectorAll('[data-remove-field]').forEach(el=>el.onclick=()=>{mark();node.config.fields.splice(+el.dataset.removeField,1);changed();renderInspector();});if($('#add-schema-field'))$('#add-schema-field').onclick=()=>{mark();node.config.fields.push({name:'field_'+(node.config.fields.length+1),type:'string',required:true});changed();renderInspector();};document.querySelectorAll('[data-route]').forEach(el=>el.onchange=()=>{if(el.value)connect(node.id,el.value,el.dataset.route);else{mark();S.workflow.edges=S.workflow.edges.filter(e=>!(e.source===node.id&&(e.port||'next')===el.dataset.route));changed();renderNodes();}});$('#delete-node').onclick=deleteSelected;}
function deleteSelected(){if(!S.selected)return;mark();S.workflow.nodes=S.workflow.nodes.filter(n=>n.id!==S.selected);S.workflow.edges=S.workflow.edges.filter(e=>e.source!==S.selected&&e.target!==S.selected);S.selected=null;changed();renderNodes();renderInspector();}
function renderConsole(){document.querySelectorAll('[data-console]').forEach(b=>b.classList.toggle('active',b.dataset.console===S.tab));const r=S.run;const active=r&&['queued','running','cancelling'].includes(r.status);$('#stop-button').hidden=!active;$('#stop-button').disabled=r?.status==='cancelling';$('#run-button').disabled=!!active||!S.bootstrap.native;$('#run-status').textContent=r?`${r.status.charAt(0).toUpperCase()+r.status.slice(1)}${r.duration_ms?' · '+(r.duration_ms/1000).toFixed(2)+'s':''}`:'Ready to run';$('#event-count').textContent=r?.events.length||0;let html='';if(S.tab==='input'){html=`<div class="input-pane"><div><textarea id="run-input" spellcheck="false" aria-label="Workflow input JSON">${esc(S.inputText)}</textarea></div><div class="input-hint"><strong>Give your workflow a starting point.</strong>Pass a JSON object. Reference its fields in prompts with <code>{{input}}</code>.<br>Then click <strong style="display:inline;font-size:10px">Run workflow</strong>.</div></div>`;}else if(!r){html='<div class="console-empty"><span class="empty-symbol">▷</span><div><strong>A little input. A lot of possibility.</strong>Run your workflow to see results here.</div></div>';}else if(S.tab==='state'){html=`<pre class="state-json">${esc(JSON.stringify(r.state,null,2))}</pre>${!Object.keys(r.state).length?'<p class="field-help">Final state appears when the run completes or pauses. Intermediate updates are in the execution trace.</p>':''}`;}else if(S.tab==='trace'){html=r.events.map(e=>`<div class="trace-row"><time>${esc(e.time.slice(11,23))}</time><strong>${esc(e.type)}</strong><code>${esc(e.node||'')}</code>${e.updates?`<span title="${esc(JSON.stringify(e.updates))}">↳ ${esc(Object.keys(e.updates).join(', '))}</span>`:''}</div>`).join('')||'<p class="field-help">Waiting for native runtime events…</p>';}else if(r.status==='suspended'){html=`<div class="approval-panel"><span class="run-badge suspended">Awaiting human input</span><div class="question">${esc(r.prompt)}</div><div class="approval-form"><input id="approval-response" value="true" aria-label="Approval response as JSON"><button class="button primary" id="resume-button">Continue run →</button></div><p class="field-help">Enter a JSON response: true, false, or a quoted message.</p></div>`;}else if(r.error){html=`<div class="error-box">${esc(r.error)}</div><button class="button small" id="recover-button" style="margin-top:8px">Recover from checkpoint</button>`;}else if(r.status==='completed'){html=`<pre class="output-text">${esc(typeof r.state.output==='string'?r.state.output:JSON.stringify(r.state.output??r.state,null,2))}</pre>`;}else{html='<div class="console-empty"><span class="empty-symbol">◌</span><div><strong>Your workflow is running.</strong>Follow each step in the execution trace.</div></div>';}$('#console-content').innerHTML=html;if($('#run-input'))$('#run-input').oninput=e=>{S.inputText=e.target.value;try{const obj=JSON.parse(S.inputText);if(obj&&typeof obj==='object'&&!Array.isArray(obj)){S.workflow.inputs=obj;changed();}}catch{}};if($('#resume-button'))$('#resume-button').onclick=async()=>{try{const response=JSON.parse($('#approval-response').value);await api(`/api/runs/${r.id}/resume`,{response});S.run.status='queued';renderConsole();pollRun(r.id);}catch(error){toast(error.message);}};if($('#recover-button'))$('#recover-button').onclick=async()=>{try{await api(`/api/runs/${r.id}/recover`,{});S.run.status='queued';S.run.error='';renderConsole();pollRun(r.id);}catch(error){toast(error.message);}};}
async function pollRun(id){clearTimeout(S.poll);try{const run=await api('/api/runs/'+id);if(!S.run||S.run.id!==id)return;S.run=run;S.nodeStatus={};for(const e of run.events){if(e.type==='node.started')S.nodeStatus[e.node]='running';if(e.type==='node.completed')S.nodeStatus[e.node]='completed';if(e.type==='node.failed')S.nodeStatus[e.node]='failed';if(e.type==='run.interrupted')S.nodeStatus[e.node]='suspended';}if(['failed','cancelled'].includes(run.status)){for(const [key,value]of Object.entries(S.nodeStatus))if(value==='running')S.nodeStatus[key]='failed';}if(run.status==='suspended'&&S.tab==='trace')S.tab='output';renderNodes();if(S.tab!=='input')renderConsole();else{const active=['queued','running','cancelling'].includes(run.status);$('#run-button').disabled=active;$('#run-status').textContent=run.status;$('#stop-button').hidden=!active;}if(['queued','running','cancelling'].includes(run.status))S.poll=setTimeout(()=>pollRun(id),250);else updateHistoryCount();}catch(error){toast(error.message);}}
async function startRun(){try{const inputs=JSON.parse(S.inputText);const data=await api('/api/runs',{workflow:clone(S.workflow),inputs,max_steps:100});S.run={id:data.id,status:'queued',events:[],state:{},duration_ms:0};S.nodeStatus={};S.tab='output';renderConsole();pollRun(data.id);}catch(error){showModal('Cannot run this workflow',`<div class="error-box">${esc(error.message)}</div>`);}}
function showModal(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}function closeModal(){$('#modal').close();}
function finishGettingStarted(){try{localStorage.setItem(ONBOARDING_KEY,'done');}catch{}}
function showGettingStarted(){showModal('Welcome to GraphCore Studio',`<p class="modal-copy">Build a workflow, run it locally, and inspect each step. Start with an offline example or connect a model when you’re ready.</p><div class="getting-started-grid"><button class="getting-started-card" id="start-offline"><span class="getting-started-icon">▷</span><strong>Try an offline example</strong><small>Run a working workflow without an API key or network call.</small></button><button class="getting-started-card featured" id="start-model"><span class="getting-started-icon">✳</span><strong>Set up a live model</strong><small>Configure OPENROUTER_API_KEY and save a model as model1, then start with a live chat workflow.</small></button><button class="getting-started-card" id="browse-templates"><span class="getting-started-icon">▦</span><strong>Browse templates</strong><small>Explore examples for research, structured output, tools, and agent teams.</small></button></div><div class="modal-actions"><button class="button quiet" id="dismiss-getting-started">Skip for now</button></div>`);$('#start-offline').onclick=()=>{finishGettingStarted();const sample=S.bootstrap.templates.find(t=>t.id==='research-studio')||S.bootstrap.templates[0];load(sample);closeModal();toast('Offline example ready. Click Run workflow to try it.');};$('#start-model').onclick=()=>{finishGettingStarted();const sample=S.bootstrap.templates.find(t=>t.id==='chat-model-playground')||S.bootstrap.templates[0];load(sample);const node=S.workflow.nodes.find(n=>n.type==='model'||n.type==='agent');if(node){node.config.provider='openrouter';node.config.model='$model1';S.selected=node.id;changed();renderAll();}closeModal();openIntegrations();};$('#browse-templates').onclick=()=>{finishGettingStarted();S.library='templates';renderLibrary();closeModal();toast('Choose a template from the left panel.');};$('#dismiss-getting-started').onclick=()=>{finishGettingStarted();closeModal();};}
function environmentRow(name,status={},custom=false){return `<div class="environment-row ${custom?'custom':''}" data-env-row><label><span>${custom?'<input data-env-name value="'+esc(name)+'" placeholder="VARIABLE_NAME" aria-label="Environment variable name">':'<strong>'+esc(name)+'</strong>'}<small>${status.stored?'Saved in local .env':status.configured?'Available from Studio environment':'Not set'}</small></span><input type="password" data-env-value="${esc(name)}" autocomplete="new-password" placeholder="${status.stored?'Saved · leave empty to keep':status.configured?'Already available · enter to override':'Enter value'}" aria-label="Value for ${esc(name)}"></label><label class="env-remove"><input type="checkbox" data-env-remove="${esc(name)}"> Remove</label></div>`;}
async function openIntegrations(){try{const [data,modelData]=await Promise.all([api('/api/settings/environment'),api('/api/settings/models')]);S.models=modelData.models;const status=new Map(data.variables.map(v=>[v.name,v]));let html='<p class="modal-copy">Configure provider credentials and other <code>.env</code> variables here. Studio saves them in its local data folder and loads them before model initialization. Secret values are write-only in this UI.</p><div class="env-security">Local file: <code>studio/data/.env</code> · file permissions are restricted where the operating system supports it.</div><div class="inspector-section">NAMED MODELS</div>';html+='<p class="modal-copy">Save models as variables, then put <code>$model1</code> in a Chat Model or Agent node’s <code>model</code> field in workflow JSON. Each node can use a different variable.</p><div id="model-rows">';for(const [name,id] of Object.entries(S.models))html+=modelRow(name,id);html+='</div><button class="button small" id="add-model">＋ Add model</button>';html+='<div class="inspector-section">PROVIDER VARIABLES</div>';const names=[...new Set(S.bootstrap.providers.flatMap(p=>p.env||[]))];if(!names.length)html+='<p class="field-help">Provider integrations do not declare API key variables.</p>';for(const name of names)html+=environmentRow(name,status.get(name));html+='<div class="inspector-section">CUSTOM .ENV VARIABLES</div><div id="custom-env-rows">';for(const v of data.variables.filter(v=>!names.includes(v.name)))html+=environmentRow(v.name,v,true);html+='</div><button class="button small" id="add-env-variable">＋ Add variable</button><div class="modal-actions"><button class="button" id="cancel-env">Cancel</button><button class="button primary" id="save-env">Save integrations</button></div><p class="field-help">Changes take effect immediately for new model calls. Shell-defined variables are available too. Avoid putting secrets in workflow JSON.</p>';showModal('Model integrations · multiple models',html);$('#cancel-env').onclick=closeModal;$('#add-model').onclick=()=>{$('#model-rows').insertAdjacentHTML('beforeend',modelRow('',''));$('#model-rows [data-model-row]:last-child [data-model-name]')?.focus();};$('#model-rows').onclick=e=>{if(e.target.matches('[data-model-remove]'))e.target.closest('[data-model-row]').remove();};$('#add-env-variable').onclick=()=>{$('#custom-env-rows').insertAdjacentHTML('beforeend',environmentRow('',{},true));document.querySelector('#custom-env-rows [data-env-row]:last-child [data-env-name]')?.focus();};$('#save-env').onclick=saveEnvironment;}catch(error){toast(error.message);}}
function showTableMapping(name,text,preview){
 const labels={string:'Text',integer:'Whole number',decimal:'Decimal (exact)',boolean:'True / false'};
 showModal('Choose column types',`<p class="modal-copy"><strong>${esc(name)}</strong> · ${preview.row_count} rows. All columns start as text. Select numeric types for calculations. Empty cells become null. True / false columns accept only true and false.</p><div class="table-mapping">${preview.columns.map((column,i)=>`<label class="table-column"><span><strong>${esc(column.name)}</strong><small>Sample: ${esc(preview.rows.map(r=>r[column.name]??'∅').join(' · ')||'No data rows')}</small></span><select data-column-type="${i}" aria-label="Type for ${esc(column.name)}">${Object.entries(labels).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label>`).join('')}</div><div id="table-mapping-error" class="error-box" role="alert" hidden></div><div class="modal-actions"><button class="button" id="cancel-table-import">Cancel</button><button class="button primary" id="confirm-table-import">Import table</button></div>`);
 document.querySelectorAll('[data-column-type]').forEach(el=>el.onchange=()=>{$('#table-mapping-error').hidden=true;});
 $('#cancel-table-import').onclick=openData;
 $('#confirm-table-import').onclick=async()=>{const button=$('#confirm-table-import'),errorBox=$('#table-mapping-error');button.disabled=true;button.textContent='Importing…';errorBox.hidden=true;try{const types=Object.create(null);document.querySelectorAll('[data-column-type]').forEach(el=>{types[preview.columns[Number(el.dataset.columnType)].name]=el.value;});await api('/api/tables',{name,text,types});await openData();toast('Table imported.');}catch(error){errorBox.hidden=false;errorBox.textContent=error.message+'. Change the column type or correct the CSV and choose it again.';button.disabled=false;button.textContent='Import table';}};
}
async function openData(){try{const data=await api('/api/tables');showModal('Data workspace',`<p class="modal-copy">Upload a local CSV (UTF-8, up to 2 MiB and 20,000 rows). Rows remain in immutable local artifacts. Previews show up to 20 rows. Empty cells become null; undeclared columns remain text.</p><button class="button primary" id="upload-table">＋ Choose CSV</button><input id="table-file" type="file" accept=".csv,text/csv" hidden><div id="table-import-error" class="error-box" role="alert" hidden></div><div class="knowledge-list">${data.tables.map(t=>`<div class="saved-row"><span><strong>${esc(t.name)}</strong><small>${t.row_count} rows · ${t.columns.length} columns</small></span><button class="button small" data-table="${esc(t.id)}">Preview / use</button></div>`).join('')||'<p class="modal-copy">No tables yet.</p>'}</div>`);$('#upload-table').onclick=()=>$('#table-file').click();$('#table-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('CSV exceeds 2 MiB');const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());const preview=await api('/api/tables/inspect',{name:file.name,text});showTableMapping(file.name,text,preview);}catch(error){$('#table-import-error').hidden=false;$('#table-import-error').textContent=error.message;}};document.querySelectorAll('[data-table]').forEach(b=>b.onclick=async()=>{try{const t=await api('/api/tables/'+b.dataset.table);const ref={type:t.type,id:t.id,name:t.name,row_count:t.row_count,columns:t.columns,source_sha256:t.source_sha256,...(t.provenance?{provenance:t.provenance}:{})};showModal(t.name,`<p class="modal-copy">${t.row_count} rows. Numeric decimals are stored as strings to preserve precision. Full rows are never inserted into workflow state automatically.</p><pre class="error-box">${esc(JSON.stringify({columns:t.columns,rows:t.rows,truncated:t.truncated},null,2))}</pre><div class="modal-actions"><button class="button primary" id="use-table">Use as workflow input “table”</button><button class="button" id="create-data-flow">Build summary workflow</button></div>`);$('#use-table').onclick=()=>{mark();S.workflow.inputs={...S.workflow.inputs,table:ref};S.inputText=JSON.stringify(S.workflow.inputs,null,2);changed();closeModal();renderAll();toast('Table reference added. Connect a Data summary node.');};$('#create-data-flow').onclick=()=>{const numeric=t.columns.find(c=>['integer','decimal'].includes(c.type));if(!numeric){toast('Import with an integer or decimal column first.');return;}closeModal();confirmReplace(()=>{load({format:'graphcore.studio.v1',id:'workflow_'+Date.now(),name:'CSV summary · '+t.name,description:'Local exact decimal calculations with source provenance. No model calls.',inputs:{table:ref},nodes:[{id:'start',type:'input',label:'Source table',x:40,y:100,config:{}},{id:'summary',type:'data',label:'Summarize '+numeric.name,x:330,y:100,config:{input_field:'table',column:numeric.name,output_key:'summary'}},{id:'result',type:'output',label:'Summary report',x:620,y:100,config:{template:'{{summary}}'}}],edges:[{source:'start',target:'summary',port:'next'},{source:'summary',target:'result',port:'next'}]});changed();});};}catch(error){toast(error.message);}});}catch(error){toast(error.message);}}
async function openKnowledge(){try{const data=await api('/api/documents');let html='<p class="modal-copy">Add local text documents for retrieval nodes. Files stay in this machine’s Studio data folder. Supported formats: .txt, .md, .csv, .json. Each file up to 1 MiB; library up to 10 MiB.</p><div class="modal-actions" style="justify-content:flex-start"><button class="button primary" id="add-documents">＋ Add documents</button><span class="field-help">'+data.documents.length+' / 100 documents</span></div><input type="file" id="knowledge-files" accept=".txt,.md,.csv,.json,text/plain,text/markdown,text/csv,application/json" multiple hidden><div class="knowledge-list">';html+=data.documents.length?data.documents.map(d=>`<div class="saved-row knowledge-row"><span><strong>${esc(d.name)}</strong><small>${d.characters.toLocaleString()} characters</small></span><button class="button small" data-remove-document="${esc(d.id)}">Remove</button></div>`).join(''):'<p class="modal-copy">Your library is empty. Add a text file, then connect a Document retrieval node between Input and a Chat Model.</p>';html+='</div><div class="inspector-note">Retrieval uses local BM25 keyword ranking. Connect the retrieval node to a Chat Model and reference <strong>{{context.results}}</strong> in its prompt to ground an answer. The result includes each passage’s source filename.</div>';showModal('Knowledge library',html);$('#add-documents').onclick=()=>$('#knowledge-files').click();$('#knowledge-files').onchange=async e=>{const files=[...e.target.files];try{for(const file of files){if(file.size>1024*1024)throw Error(file.name+' exceeds 1 MiB');await api('/api/documents',{name:file.name,text:await file.text()});}toast(files.length+' document'+(files.length===1?'':'s')+' added to the local library.');await openKnowledge();}catch(error){toast(error.message);}e.target.value='';};document.querySelectorAll('[data-remove-document]').forEach(button=>button.onclick=async()=>{try{await api('/api/documents/'+button.dataset.removeDocument,undefined,'DELETE');await openKnowledge();toast('Document removed.');}catch(error){toast(error.message);}});}catch(error){toast(error.message);}}
function modelRow(name,id){return `<div class="model-row" data-model-row><input data-model-name value="${esc(name)}" placeholder="model1" aria-label="Model variable name"><span>→</span><input data-model-id value="${esc(id)}" placeholder="openai/gpt-4o-mini" aria-label="OpenRouter model ID"><button type="button" data-model-remove aria-label="Remove model">×</button></div>`;}
async function saveEnvironment(){const models={};for(const row of document.querySelectorAll('[data-model-row]')){const name=row.querySelector('[data-model-name]').value.trim(),id=row.querySelector('[data-model-id]').value.trim();if(!name&&!id)continue;if(!name||!id){toast('Each model needs a name and OpenRouter ID.');return;}if(Object.prototype.hasOwnProperty.call(models,name)){toast('Model variable names must be unique.');return;}models[name]=id;}const values={},remove=[];for(const row of document.querySelectorAll('[data-env-row]')){const nameField=row.querySelector('[data-env-name]'),secret=row.querySelector('[data-env-value]'),removeBox=row.querySelector('[data-env-remove]');const name=(nameField?nameField.value:secret.dataset.envValue).trim();if(!name)continue;if(removeBox?.checked){remove.push(name);continue;}if(secret.value)values[name]=secret.value;}try{const result=await api('/api/settings/models',{models});S.models=result.models;await api('/api/settings/environment',{values,remove});closeModal();renderNodes();renderInspector();toast('Models and environment saved locally.');}catch(error){toast(error.message);}}
async function save(){try{await api('/api/workflows',{workflow:S.workflow});S.dirty=false;$('#save-status').textContent='Saved locally';toast('Workflow saved on this machine.');}catch(error){toast(error.message);}}
function showJSON(){showModal('Your workflow, as a document',`<p class="modal-copy">Export a portable JSON workflow, or edit and apply it here.</p><textarea id="workflow-json" class="modal-code" spellcheck="false">${esc(JSON.stringify(S.workflow,null,2))}</textarea><div class="modal-actions"><button class="button" id="import-json">Import file</button><button class="button" id="export-json">Export JSON</button><button class="button primary" id="apply-json">Apply changes</button></div>`);$('#import-json').onclick=()=>$('#import-file').click();$('#export-json').onclick=()=>{const blob=new Blob([$('#workflow-json').value],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(S.workflow.id||'workflow')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#apply-json').onclick=()=>{try{const value=JSON.parse($('#workflow-json').value);checkDocument(value);mark();S.workflow=value;S.inputText=JSON.stringify(value.inputs||{},null,2);S.selected=value.nodes[0]?.id;changed();closeModal();renderAll();fit();}catch(error){toast(error.message);}};}
function checkDocument(w){if(!w||w.format!=='graphcore.studio.v1'||!Array.isArray(w.nodes)||!Array.isArray(w.edges)||w.nodes.length>100||w.edges.length>300)throw Error('Unsupported workflow document');const ids=new Set();for(const n of w.nodes){if(!n||!Object.prototype.hasOwnProperty.call(META,n.type)||typeof n.id!=='string'||!/^[A-Za-z_][A-Za-z0-9_]{0,63}$/.test(n.id)||ids.has(n.id)||!Number.isFinite(n.x)||!Number.isFinite(n.y)||!n.config||typeof n.config!=='object'||Array.isArray(n.config))throw Error('Invalid node definition');if(n.type==='schema'&&(!Array.isArray(n.config.fields)||n.config.fields.some(f=>!f||typeof f.name!=='string'||typeof f.type!=='string')))throw Error('Invalid schema fields');ids.add(n.id);}for(const e of w.edges)if(!e||!ids.has(e.source)||!ids.has(e.target))throw Error('Connection references a missing node');if(typeof w.name!=='string'||typeof w.id!=='string')throw Error('Workflow name and ID are required');}
async function openSaved(){try{const items=await api('/api/workflows');showModal('Open a workflow',items.length?items.map((w,i)=>`<button class="saved-row" data-saved="${i}"><strong>${esc(w.name)}</strong><small>${w.nodes?.length||0} nodes →</small></button>`).join(''):'<p class="modal-copy">No saved workflows yet. Save your draft, or start from a template.</p>');document.querySelectorAll('[data-saved]').forEach(b=>b.onclick=()=>{const w=items[+b.dataset.saved];try{checkDocument(w);closeModal();confirmReplace(()=>load(w));}catch(error){toast(error.message);}});}catch(error){toast(error.message);}}
async function updateHistoryCount(){try{$('#run-count').textContent=(await api('/api/runs')).length;}catch{}}
async function history(){try{const runs=await api('/api/runs');showModal('Run history',runs.length?runs.map(r=>`<button class="saved-row" data-run="${esc(r.id)}"><span><strong>${esc(r.name)}</strong><br><small>${esc(new Date(r.created).toLocaleString())} · ${(r.duration_ms/1000).toFixed(2)}s</small></span><span class="run-badge ${esc(r.status)}">${esc(r.status)}</span></button>`).join(''):'<p class="modal-copy">Your runs will appear here, including approvals waiting for a response.</p>');document.querySelectorAll('[data-run]').forEach(b=>b.onclick=async()=>{try{const r=await api('/api/runs/'+b.dataset.run);closeModal();confirmReplace(()=>{load(r.workflow);S.run=r;S.tab='output';pollRun(r.id);});}catch(error){toast(error.message);}});}catch(error){toast(error.message);}}
function help(){showModal('A visual workspace for local agents',`<div class="modal-copy"><p><strong>Build:</strong> drag nodes from the library or click to add one. Drag a node to arrange it.</p><p><strong>Connect:</strong> click an output dot, then an input dot. You can also choose targets in Node settings.</p><p><strong>Configure:</strong> select a node, set its prompts, tools, schema, or condition. Use <code>{{field}}</code> to reference state.</p><p><strong>Run:</strong> edit the Input JSON and run. Inspect Output, State, or the native execution trace.</p><p><strong>Knowledge:</strong> add local text documents, then use a Document retrieval node and reference its passages in a model prompt.</p><p><strong>Models:</strong> add named model variables in Model integrations, then select $model1 in each Chat Model or Agent node. Configure OPENROUTER_API_KEY there too. The offline fixture makes no AI request.</p><p><strong>Shortcuts:</strong> <kbd>Ctrl/Cmd Z</kbd> undo, <kbd>Delete</kbd> remove selected node, <kbd>Escape</kbd> cancel connection. Scroll to pan; Ctrl/Cmd + scroll to zoom.</p><p>Scheduling, checkpoints, and equality conditions run in C++. Model and tool integrations run in Python. Agent handoffs are sequential in this release.</p></div>`);}
async function boot(){try{S.bootstrap=await api('/api/bootstrap');S.models=(await api('/api/settings/models')).models;$('#engine-status').innerHTML=`<i></i> ${S.bootstrap.native?'C++ engine connected':'Engine needs a build'}`;if(!S.bootstrap.native)toast(S.bootstrap.native_error);let workflow=S.bootstrap.templates[0],hasDraft=false;try{const draft=JSON.parse(localStorage.getItem('graphcore.studio.draft'));if(draft){checkDocument(draft);workflow=draft;hasDraft=true;}}catch{}load(workflow);updateHistoryCount();if(!hasDraft&&!localStorage.getItem(ONBOARDING_KEY))showGettingStarted();}catch(error){$('#engine-status').textContent='Server unavailable';toast(error.message);}}
$('#node-search').oninput=renderLibrary;document.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>{S.library=b.dataset.library;renderLibrary();});document.querySelectorAll('[data-console]').forEach(b=>b.onclick=()=>{S.tab=b.dataset.console;renderConsole();});$('#workflow-name').onchange=e=>{mark();S.workflow.name=e.target.value||'Untitled workflow';$('#breadcrumb').textContent=S.workflow.name;changed();};$('#settings-toggle').onclick=()=>document.querySelector('.inspector').classList.toggle('mobile-open');$('#close-inspector').onclick=()=>document.querySelector('.inspector').classList.remove('mobile-open');$('#save-button').onclick=save;$('#clear-button').onclick=()=>{showModal('Clear this workflow?',`<p class="modal-copy">Remove all nodes and connections from the current canvas? You can undo this action.</p><div class="modal-actions"><button class="button" id="cancel-clear">Keep workflow</button><button class="button danger" id="confirm-clear">Clear workflow</button></div>`);$('#cancel-clear').onclick=closeModal;$('#confirm-clear').onclick=()=>{mark();S.workflow.nodes=[];S.workflow.edges=[];S.selected=null;S.connection=null;S.nodeStatus={};S.run=null;if(S.poll){clearTimeout(S.poll);S.poll=null;}changed();renderAll();closeModal();fit();};};$('#open-button').onclick=openSaved;$('#run-button').onclick=startRun;$('#history-button').onclick=history;$('#integrations-button').onclick=openIntegrations;$('#knowledge-button').onclick=openKnowledge;$('#data-button').onclick=openData;$('#builder-button').onclick=()=>$('#canvas-area').focus();$('#help-button').onclick=help;$('#add-note-button').onclick=help;$('#json-button').onclick=showJSON;$('#modal-close').onclick=closeModal;$('#validate-button').onclick=async()=>{try{const data=await api('/api/validate',{workflow:S.workflow});showModal(data.errors.length?'A few connections need attention':'Your workflow is ready',data.errors.length?`<div class="error-box">${esc(data.errors.join('\n'))}</div>`:'<div class="success-box">All nodes and routes are valid.<br>Run the workflow to test its behavior with your input.</div>');}catch(error){toast(error.message);}};$('#stop-button').onclick=async()=>{try{await api(`/api/runs/${S.run.id}/cancel`,{});toast('Stop requested. Active callbacks must finish before execution stops.');pollRun(S.run.id);}catch(error){toast(error.message);}};$('#zoom-in').onclick=()=>zoom(1.15);$('#zoom-out').onclick=()=>zoom(1/1.15);$('#fit-button').onclick=fit;$('#undo-button').onclick=()=>{if(!S.undo.length)return;S.redo.push(clone(S.workflow));S.workflow=S.undo.pop();changed();renderAll();};$('#redo-button').onclick=()=>{if(!S.redo.length)return;S.undo.push(clone(S.workflow));S.workflow=S.redo.pop();changed();renderAll();};$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Workflow file exceeds 2 MiB');const value=JSON.parse(await file.text());checkDocument(value);closeModal();confirmReplace(()=>{load(value);changed();});}catch(error){toast(error.message);}e.target.value='';};const canvas=$('#canvas-area');canvas.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';});canvas.addEventListener('drop',e=>{e.preventDefault();const kind=e.dataTransfer.getData('application/graphcore-node');if(META[kind]){const p=worldPoint(e);addNode(kind,p.x-113,p.y-54);}});canvas.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('.canvas-node,.canvas-controls'))return;drag={type:'pan',x:e.clientX,y:e.clientY,vx:S.view.x,vy:S.view.y};});canvas.addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey){const rect=canvas.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.005),e.clientX-rect.left,e.clientY-rect.top);}else{S.view.x-=e.deltaX;S.view.y-=e.deltaY;applyView();}},{passive:false});document.addEventListener('keydown',e=>{if(e.key==='Escape'){S.connection=null;drawEdges();$('#canvas-hint').textContent='Drag to arrange · connect the dots to build a flow';}if(e.target.matches('input,textarea,select')||$('#modal').open)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('#redo-button'):$('#undo-button')).click();}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();}if(e.key==='/'){e.preventDefault();$('#node-search').focus();}});window.addEventListener('resize',()=>drawEdges());boot();
